  'guide.tailwind.props.table.r5c2': 'eixo de cantos',
  'guide.tailwind.props.table.r5c3': '<code>gf-square/sharp</code>',
  'guide.tailwind.props.table.r6c1': '<code>/w1</code> a <code>/w3</code>',
  'guide.tailwind.props.table.r6c2': 'eixo de peso',
  'guide.tailwind.props.table.r6c3': '<code>gf-search/w1.5</code>',
  'guide.tailwind.props.table.r7c1': '<code>/tl</code>, <code>/tr</code>, <code>/bl</code>, <code>/br</code>',
  'guide.tailwind.props.table.r7c2': 'canto do selo',
